// === Tab: mySketch ===
// Attractor_11.0

let G = 1000 ; let H = 0.99 ; 

let X ; let Y ; let dX ;let dY ; let PX ; let PY ; long MLS; let Q ; let Qmax ; let T ;
let L ; let CX[] = new Array(3) ; let CY[] = new Array(3) ; let I ; let C ; 

function setup(){

  createCanvas(800, 400) ; noSmooth() ; background(0) ;
  for ( I = 0 ; I < 3 ; I++ ){
    CX[I] = random(50,350) ; CY[I] = random(50,350) ;
  }

}// setup()

function draw(){

  stroke(0) ; fill(0,0,0,60) ; rect(400,0,400,400) ;
  for ( Q = 0 ; Q < Qmax ; Q++ ){
    X = PX ; Y = PY ; dX = 0 ; dY = 0 ; C = 100000 ;
    while ( C > 2 ){
      C = C - 1 ;
      for ( I = 0 ; I < 3 ; I++ ){
        L = sqrt(pow(X-CX[I],2)+pow(Y-CY[I],2)) +10 ;
        if ( L < 12 ){ C = I ; }
        dX = dX + (G*(CX[I]-X)/pow(L,3)) ;
        dY = dY + (G*(CY[I]-Y)/pow(L,3)) ;
      }
      dX = dX * H ; dY = dY * H ;
      X = X + dX ; Y = Y + dY ; 
      if ( X > 0 ){ stroke(255) ; point(X+400,Y) ; } 
    }
    if ( C == 0 ){ stroke(255,0,0) ; }
    if ( C == 1 ){ stroke(0,255,0) ; }
    if ( C == 2 ){ stroke(0,0,255) ; }
    point(PX,PY) ;
    PX = PX + 1 ; 
    if ( PX >= 400 ){ PX = 0 ; PY = PY + 1 ; }
    if ( PY >= 400 ){ PX = 0 ; PY = 0 ; }    
  }
  stroke(255,0,0) ; fill(255,0,0) ; ellipse(CX[0]+400,CY[0],10,10) ;
  stroke(0,255,0) ; fill(0,255,0) ; ellipse(CX[1]+400,CY[1],10,10) ;
  stroke(0,0,255) ; fill(0,0,255) ; ellipse(CX[2]+400,CY[2],10,10) ;
  if ( millis() - MLS > 20 && Qmax > 1 ){ Qmax = Qmax - 1 ; }else{ Qmax = Qmax + 1 ; }
  MLS = millis() ; 

}//draw()

function mousePressed(){ setup() ; }

